async function reserveLastItem(id: string): Promise<boolean> {
  const item = await db.items.find(id);
  if (!item || item.stock <= 0) return false;
  await payment.authorize(item.price);
  await db.items.update(id, { stock: item.stock - 1 });
  return true;
}
